Proof.
  intros f g H. assert (X : forallb (fun e => tail_edgeb (fst e) (snd e)) TAIL_EDGES = true) by (vm_compute; reflexivity).
  exact (proj1 (forallb_forall _ _) X _ H).
Qed.
Lemma leaf_edge_ok : forall f r, In (f, r) LEAF_EDGES -> leaf_edgeb f r = true.
Proof.
  intros f r H. assert (X : forallb (fun e => leaf_edgeb (fst e) (snd e)) LEAF_EDGES = true) by (vm_compute; reflexivity).
  exact (proj1 (forallb_forall _ _) X _ H).
Qed.
Lemma leaf_tail_ok : forall f, In f LEAF_TAILS -> leaf_tailb f = true.
Proof.
  intros f H. assert (X : forallb leaf_tailb LEAF_TAILS = true) by (vm_compute; reflexivity).
  exact (proj1 (forallb_forall _ _) X _ H).
Qed.
Lemma root_ok : forall r g, In (r, g) ROOT_CALLS -> site_ctx g [r].
Proof.
  intros r g H. apply site_ctx_root. assert (X : forallb (fun e => site_ctxb (snd e) [fst e]) ROOT_CALLS = true) by (vm_compute; reflexivity).
  exact (proj1 (forallb_forall _ _) X _ H).
Qed.
